import { ARROWS, EPSILON_WORDS, lexSymbols, stripComment, symbolList } from './symbols'

export const EOF = '$'
export const SEP = '\u0001'

export interface Rule {
  lhs: string
  rhs: string[]
  line: number
}

export interface Problem {
  level: 'bad' | 'warn' | 'ok' | 'info'
  text: string
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Lexing, comments and ε-words come from the shared symbol syntax module (re-exported for old imports).
export { lexSymbols, stripComment, symbolList } from './symbols'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Splits a rule line at its first unquoted arrow; the left side is lexed like any other symbol, so a quoted
//          left side ("E'" or '|') is the symbol inside the quotes. Null when the line has no arrow.
function splitRule(line: string) {
  for (const tok of lexSymbols(line)) {
    if (tok.quoted) continue
    const hits = ARROWS.map((a) => ({ a, at: tok.text.indexOf(a) })).filter((h) => h.at >= 0)
    if (!hits.length) continue
    const { a, at } = hits.reduce((x, y) => (y.at < x.at ? y : x))
    const lhs = lexSymbols(line.slice(0, tok.start + at)).filter((t) => t.text !== '')
    return { lhs: lhs.length === 1 ? lhs[0].text : null, lhsCount: lhs.length, rhsText: line.slice(tok.start + at + a.length) }
  }
  return null
}

export function parseGrammar(text: string) {
  const rules: Rule[] = []
  const errors: string[] = []
  let lastLhs: string | null = null
  ;(text || '').split('\n').forEach((raw, idx) => {
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Can you add support for inline comments to P definition"
    // Changes: Inline comments are cut off before parsing (a whole-line comment becomes an empty line).
    const line = stripComment(raw).trim()
    if (!line) return
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
    // Changes: The left side is found with the shared lexer (quotes respected) instead of a regex of its own.
    let lhs: string
    let rhsText: string
    const split = splitRule(line)
    if (split?.lhs) {
      lhs = split.lhs
      rhsText = split.rhsText
      lastLhs = lhs
    } else if (line.startsWith('|') && lastLhs) {
      lhs = lastLhs
      rhsText = line.slice(1)
    } else {
      errors.push(
        !split
          ? `Riadok ${idx + 1}: chýba „->“ (${line})`
          : split.lhsCount
            ? `Riadok ${idx + 1}: ľavá strana pravidla musí byť jeden neterminál (${line})`
            : `Riadok ${idx + 1}: chýba ľavá strana pravidla (${line})`,
      )
      return
    }
    let alt: string[] = []
    const alts = [alt]
    for (const tok of lexSymbols(rhsText)) {
      if (!tok.quoted && tok.text === '|') alts.push((alt = []))
      else if (!tok.quoted && EPSILON_WORDS.has(tok.text)) continue
      else alt.push(tok.text)
    }
    alts.forEach((rhs) => rules.push({ lhs, rhs, line: idx + 1 }))
  })
  return { rules, errors }
}

export const ruleText = (r: Pick<Rule, 'lhs' | 'rhs'>) => `${r.lhs} → ${r.rhs.length ? r.rhs.join(' ') : 'ε'}`

export const fmtSet = (arr: string[]) => (arr.length ? `{ ${arr.join(', ')} }` : '∅')

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: N (S first) and T are decided by the grammar module (analysis.ts) and passed in, so the LL analysis
//          and the formal definition can no longer disagree. Not for components – use analyzeGrammar.
export function analyzeLL(rules: Rule[], symbols: { N: string[]; T: string[] }) {
  const N = symbols.N
  const isN = new Set(N)
  const T = symbols.T.filter((t) => !isN.has(t))
  const cols = [...T.filter((t) => t !== EOF), EOF]

  const empty = new Set<string>()
  let changed = true
  while (changed) {
    changed = false
    for (const r of rules) {
      if (!empty.has(r.lhs) && r.rhs.every((s) => empty.has(s))) {
        empty.add(r.lhs)
        changed = true
      }
    }
  }

  const first = new Map(N.map((n) => [n, new Set<string>()]))
  const firstSeq = (seq: string[]) => {
    const set = new Set<string>()
    for (const s of seq) {
      if (isN.has(s)) first.get(s)!.forEach((x) => set.add(x))
      else set.add(s)
      if (!empty.has(s)) return { set, nullable: false }
    }
    return { set, nullable: true }
  }
  changed = true
  while (changed) {
    changed = false
    for (const r of rules) {
      const f = first.get(r.lhs)!
      for (const x of firstSeq(r.rhs).set) {
        if (!f.has(x)) {
          f.add(x)
          changed = true
        }
      }
    }
  }

  const follow = new Map(N.map((n) => [n, new Set<string>()]))
  if (N.length) follow.get(N[0])!.add(EOF)
  changed = true
  while (changed) {
    changed = false
    for (const r of rules) {
      r.rhs.forEach((s, i) => {
        if (!isN.has(s)) return
        const fs = follow.get(s)!
        const add = (x: string) => {
          if (!fs.has(x)) {
            fs.add(x)
            changed = true
          }
        }
        const { set, nullable } = firstSeq(r.rhs.slice(i + 1))
        set.forEach(add)
        if (nullable) follow.get(r.lhs)!.forEach(add)
      })
    }
  }

  const predict = rules.map((r) => {
    const { set, nullable } = firstSeq(r.rhs)
    const p = new Set(set)
    if (nullable) follow.get(r.lhs)!.forEach((x) => p.add(x))
    return p
  })

  const table = new Map(N.map((n) => [n, new Map<string, number[]>()]))
  rules.forEach((r, i) =>
    predict[i].forEach((a) => {
      const row = table.get(r.lhs)!
      if (!row.has(a)) row.set(a, [])
      row.get(a)!.push(i + 1)
    }),
  )
  const conflicts: { A: string; a: string; rules: number[] }[] = []
  N.forEach((A) =>
    cols.forEach((a) => {
      const cell = table.get(A)!.get(a)
      if (cell && cell.length > 1) conflicts.push({ A, a, rules: cell })
    }),
  )

  // Left recursion: A ⇒+ A… through a nullable prefix.
  const edges = new Map(N.map((n) => [n, new Set<string>()]))
  rules.forEach((r) => {
    for (const s of r.rhs) {
      if (isN.has(s)) edges.get(r.lhs)!.add(s)
      if (!empty.has(s)) break
    }
  })
  const leftRec = N.filter((n) => {
    const seen = new Set<string>()
    const stack = [...edges.get(n)!]
    while (stack.length) {
      const x = stack.pop()!
      if (x === n) return true
      if (seen.has(x)) continue
      seen.add(x)
      edges.get(x)!.forEach((y) => stack.push(y))
    }
    return false
  })

  const reach = new Set(N.length ? [N[0]] : [])
  const queue = [...reach]
  while (queue.length) {
    const x = queue.pop()!
    rules
      .filter((r) => r.lhs === x)
      .forEach((r) =>
        r.rhs.forEach((s) => {
          if (isN.has(s) && !reach.has(s)) {
            reach.add(s)
            queue.push(s)
          }
        }),
      )
  }
  const unreachable = N.filter((n) => !reach.has(n))

  const productive = new Set<string>()
  changed = true
  while (changed) {
    changed = false
    for (const r of rules) {
      if (!productive.has(r.lhs) && r.rhs.every((s) => !isN.has(s) || productive.has(s))) {
        productive.add(r.lhs)
        changed = true
      }
    }
  }
  const unproductive = N.filter((n) => !productive.has(n))

  const seenRules = new Map<string, number>()
  const duplicates: [number, number][] = []
  rules.forEach((r, i) => {
    const k = r.lhs + SEP + r.rhs.join(SEP)
    if (seenRules.has(k)) duplicates.push([seenRules.get(k)!, i + 1])
    else seenRules.set(k, i + 1)
  })

  const order = (set: Set<string>) => cols.filter((c) => set.has(c))
  return {
    rules,
    N,
    T: cols.slice(0, -1),
    cols,
    empty,
    first,
    follow,
    predict,
    table,
    conflicts,
    leftRec,
    unreachable,
    unproductive,
    duplicates,
    order,
    eofUsed: T.includes(EOF),
  }
}

export type LLAnalysis = ReturnType<typeof analyzeLL>

export function llProblems(errors: string[], a: LLAnalysis | null): Problem[] {
  const probs: Problem[] = errors.map((text) => ({ level: 'bad', text }))
  if (!a) {
    if (!errors.length) probs.push({ level: 'info', text: 'Zatiaľ žiadne pravidlá.' })
    return probs
  }
  a.conflicts.forEach((c) => probs.push({ level: 'bad', text: `Konflikt [${c.A}, ${c.a}]: pravidlá ${c.rules.join(', ')}` }))
  a.unproductive.forEach((n) => probs.push({ level: 'bad', text: `Neterminál ${n} nevygeneruje žiadny reťazec terminálov` }))
  a.leftRec.forEach((n) => probs.push({ level: 'bad', text: `Ľavá rekurzia cez ${n}` }))
  a.unreachable.forEach((n) => probs.push({ level: 'warn', text: `Neterminál ${n} je nedosiahnuteľný zo štartu ${a.N[0]}` }))
  a.duplicates.forEach(([x, y]) => probs.push({ level: 'warn', text: `Pravidlá ${x} a ${y} sú rovnaké` }))
  a.T.filter((t) => /^<.+>$/.test(t)).forEach((t) =>
    probs.push({ level: 'warn', text: `${t} vyzerá ako neterminál, ale nemá pravidlo – berie sa ako terminál` }),
  )
  if (a.eofUsed) probs.push({ level: 'info', text: `Symbol ${EOF} je použitý v gramatike – v tabuľke splýva s koncom vstupu` })
  if (!a.conflicts.length && !a.leftRec.length && !a.unproductive.length) {
    probs.unshift({
      level: 'ok',
      text: `Gramatika je LL(1): ${a.rules.length} pravidiel, ${a.N.length} neterminálov, ${a.T.length} terminálov`,
    })
  }
  return probs
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "OK it looks good, now implement it. you can use subagents for the different parts of the implemetation. After the implemetation deploy it." (plan: reduced LL table + step-by-step simulation)
// Changes: Structured step data – stack symbols, input position, step kind, applied rule and the table cell looked up.
export interface LLTraceRow {
  stack: string
  input: string
  action: string
  stackSyms: string[]
  pos: number
  kind: 'expand' | 'match' | 'accept' | 'error'
  rule?: number
  cell?: [string, string]
  pushed?: number
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "the $ is the starting non terminal from definition, could you fix that for the simulator" (answer: Use EOF_TOKEN not $)
// Changes: End marker of the input – the terminal every rule of S ends with (e.g. PROGRAM -> ... EOF_TOKEN), else $.
export function endMarker(a: LLAnalysis) {
  const ends = a.rules.filter((r) => r.lhs === a.N[0]).map((r) => r.rhs[r.rhs.length - 1])
  const last = ends[0]
  return last && last !== EOF && a.T.includes(last) && ends.every((e) => e === last) ? last : EOF
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "the $ is the starting non terminal from definition, could you fix that for the simulator" (answer: Use EOF_TOKEN not $)
// Changes: With a grammar end token the input ends with it (added when missing) instead of $, the stack starts
//          with S only and the parse succeeds once the stack is empty and the whole input is read.
export function simulateLL(a: LLAnalysis, inputText: string) {
  const toks = symbolList(inputText)
  if (!toks.length) return null
  const isN = new Set(a.N)
  const end = endMarker(a)
  const custom = end !== EOF
  const input = custom ? (toks[toks.length - 1] === end ? toks : [...toks, end]) : [...toks, EOF]
  const stack = custom ? [a.N[0]] : [EOF, a.N[0]]
  const output: number[] = []
  const rows: LLTraceRow[] = []
  let pos = 0
  let result: { ok: boolean; message: string } | null = null
  for (let step = 0; step < 5000 && !result; step++) {
    const X = stack[stack.length - 1]
    const b = input[pos] ?? EOF
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "OK it looks good, now implement it. you can use subagents for the different parts of the implemetation. After the implemetation deploy it." (plan: reduced LL table + step-by-step simulation)
    // Changes: Each row also records the stack, input position, step kind, rule, looked-up cell and pushed count.
    const row: LLTraceRow = {
      stack: stack.join(' ') || 'ε',
      input: input.slice(pos).join(' ') || 'ε',
      action: '',
      stackSyms: [...stack],
      pos,
      kind: 'error',
    }
    rows.push(row)
    if (X === undefined) {
      row.action = pos >= input.length ? 'úspech' : 'chyba'
      row.kind = pos >= input.length ? 'accept' : 'error'
      result =
        pos >= input.length
          ? { ok: true, message: `Úspech. Ľavý rozbor: ${output.join(' ')}` }
          : { ok: false, message: `Zásobník je prázdny, na vstupe zostáva ${input.slice(pos).join(' ')}` }
    } else if (X === EOF && b === EOF) {
      row.action = 'úspech'
      row.kind = 'accept'
      result = { ok: true, message: `Úspech. Ľavý rozbor: ${output.join(' ')}` }
    } else if (!isN.has(X)) {
      if (X === b) {
        stack.pop()
        pos++
        row.action = `pop ${X}, čítaj`
        row.kind = 'match'
      } else {
        row.action = 'chyba'
        result = { ok: false, message: `Očakávaný ${X}, na vstupe ${b}` }
      }
    } else {
      const cell = a.table.get(X)!.get(b)
      row.cell = [X, b]
      if (!cell) {
        row.action = 'chyba'
        result = { ok: false, message: `Prázdna bunka [${X}, ${b}]` }
      } else {
        const r = a.rules[cell[0] - 1]
        stack.pop()
        for (let i = r.rhs.length - 1; i >= 0; i--) stack.push(r.rhs[i])
        output.push(cell[0])
        row.action = `${cell[0]}: ${ruleText(r)}${cell.length > 1 ? ' (konflikt!)' : ''}`
        row.kind = 'expand'
        row.rule = cell[0]
        row.pushed = r.rhs.length
      }
    }
  }
  return { rows, end, input, ...(result ?? { ok: false, message: 'Príliš veľa krokov (cyklus?)' }) }
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "OK it looks good, now implement it. you can use subagents for the different parts of the implemetation. After the implemetation deploy it." (plan: reduced LL table + step-by-step simulation)
// Changes: Rows and columns of the LL table that the simulation looked up (also the empty cell of an error), in table order.
export function reducedTable(a: LLAnalysis, rows: LLTraceRow[]) {
  const used = rows.flatMap((r) => (r.cell ? [r.cell] : []))
  const rowSet = new Set(used.map((c) => c[0]))
  const colSet = new Set(used.map((c) => c[1]))
  return { N: a.N.filter((n) => rowSet.has(n)), cols: a.cols.filter((c) => colSet.has(c)) }
}
